def find_earliest_ABC(N):
    # Generate numbers with identical digits up to 999
    identical_digit_numbers = []
    for digit in range(1, 10):
        for length in range(1, 4):
            num = int(str(digit) * length)
            if num >= 100:
                identical_digit_numbers.append(num)

    # Sort the list to enable binary search
    identical_digit_numbers.sort()

    # Perform binary search to find the smallest number >= N
    left, right = 0, len(identical_digit_numbers) - 1
    while left <= right:
        mid = (left + right) // 2
        if identical_digit_numbers[mid] < N:
            left = mid + 1
        else:
            return identical_digit_numbers[mid]

